package cli

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/terraform-providers/terraform-provider-datadog/generator/internal/emit"
	"github.com/terraform-providers/terraform-provider-datadog/generator/internal/split"
)

// TestGenerateOutputSplitsWithOwnerTag runs a real generate into a repo-shaped
// tree and splits it against an empty base: every generated file must route to
// an artifact bundle, and the bundled source carries the owner-tag marker a
// scoped --reconcile relies on.
func TestGenerateOutputSplitsWithOwnerTag(t *testing.T) {
	root := t.TempDir()
	base, gen, out := filepath.Join(root, "base"), filepath.Join(root, "gen"), filepath.Join(root, "out")
	for _, dir := range []string{base, gen} {
		if _, err := emit.SyncGeneratedDatasources(filepath.Join(dir, "datadog", "fwprovider", "datasources_generated.go"), nil, false); err != nil {
			t.Fatal(err)
		}
	}
	if err := runTfgen("generate",
		"--spec", filepath.Join("..", "testdata", "mini-oas", "scripts", "gen-test", "teams.yaml"),
		"--output-root", filepath.Join(gen, "datadog", "fwprovider"),
		"--tests-output-root", filepath.Join(gen, "datadog", "tests"),
		"--docs-root", filepath.Join(gen, "docs", "data-sources"),
		"--examples-output-root", filepath.Join(gen, "examples", "data-sources"),
		"--report", filepath.Join(root, "report.json")); err != nil {
		t.Fatal(err)
	}

	rep, err := split.Split(split.Options{BaseDir: base, GeneratedDir: gen, OutDir: out})
	if err != nil {
		t.Fatalf("split failed: %v (errors: %v)", err, rep.Errors)
	}
	src, err := os.ReadFile(filepath.Join(out, "teams", "datadog", "fwprovider", "data_source_datadog_teams.go"))
	if err != nil {
		t.Fatal(err)
	}
	if tag, ok := emit.GeneratedOwnerTag(src); !ok || tag != "Teams" {
		t.Errorf("bundled source owner tag = %q, %v; want \"Teams\"", tag, ok)
	}
	if !strings.Contains(string(src), "Code generated by tfgen") {
		t.Error("bundled source lost the generated-code marker")
	}
}
